(() => {
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const pill=(ok,yes='READY',no='ATTENTION')=>`<span class="beast-pill ${ok?'live':'bad'}">${ok?yes:no}</span>`;
  function renderer(){
    const root=document.createElement('div'); root.className='beast-page beast-compute-control-page';
    root.innerHTML=`<header class="beast-page-head"><div><h2>Compute Control</h2><div class="sub">INTERCEPTION → VERIFIED REUSE → CRYSTALLIZATION → DURABLE OPERATIONS</div></div><div class="beast-page-actions"><button class="beast-button secondary" data-control="reconcile">Reconcile Services</button><button class="beast-button hot" data-control="refresh">Refresh Control Plane</button></div></header><section class="beast-metric-grid" data-control-metrics></section><div class="compute-control-grid"><section class="beast-card" data-control-flow></section><section class="beast-card" data-control-services></section><section class="beast-card" data-control-host></section><section class="beast-card" data-control-continuity></section></div>`;
    let disposed=false,lastControlSignature='';
    root.style.overflowAnchor='none';
    const render=state=>{if(disposed)return;const c=state.control||{};const signature=JSON.stringify(c);if(signature===lastControlSignature)return;lastControlSignature=signature;const errors=c.errors||{},i=c.interception||{},r=c.reuse||{},s=c.services||{},g=c.cgroup||{},b=c.reboot||{},h=c.host||{};const caps=h.capabilities||[];const active=(s.services&&Object.keys(s.services).length)||0;const issue=name=>errors[name]?`<p class="tiny">Unavailable: ${esc(errors[name])}</p>`:'';
      const cgroupControllers=(g.delegated_controllers||[]).length?(g.delegated_controllers||[]):(g.available_controllers||[]);
      const cgroupLabel=(g.delegated_controllers||[]).length?'delegated writable controllers':g.delegation_proven?'controllers available for approved mission delegation':'controller delegation unavailable';
      root.querySelector('[data-control-metrics]').innerHTML=[['Ingress',i.ready===true?'Governed':'Unknown','HTTP interception'],['Reuse',r.storage?.total_reuse_count??'n/a','verified credits'],['Services',active,'declared .test routes'],['Cgroup',cgroupControllers.join(', ')||'unavailable',cgroupLabel]].map(x=>`<article class="beast-card compact"><h3>${x[0]}</h3><strong class="metric small">${esc(x[1])}</strong><span class="tiny">${esc(x[2])}</span></article>`).join('');
      root.querySelector('[data-control-flow]').innerHTML=`<header class="beast-panel-head"><div><h3>Governed request flow</h3><span>Every client ingress should leave durable evidence.</span></div>${pill(i.ready===true)}</header><p><b>Ingress:</b> ${esc(i.status||'unreported')} · ${esc(i.routes?.provider_compatibility||'provider route unreported')}</p>${issue('interception')}<p><b>Reuse:</b> ${esc(r.runtime_order?.join(' → ')||'reuse state unavailable')}</p>${issue('reuse')}<p class="tiny">Use Models for route selection and Chronicle for the resulting evidence trail.</p>`;
      root.querySelector('[data-control-services]').innerHTML=`<header class="beast-panel-head"><div><h3>Published service plane</h3><span>Only healthy loopback contracts should be rendered.</span></div>${pill(active>0,'STAGED','EMPTY')}</header><p>${esc(s.registry_digest||'No registry digest')} · proxy :${esc(s.reverse_proxy_port||'n/a')}</p><div class="tiny">${Object.values(s.health||{}).map(x=>`${x.hostname} · ${x.status}`).join('<br>')||'Refresh or reconcile to load health contracts.'}</div>${issue('services')}`;
      root.querySelector('[data-control-host]').innerHTML=`<header class="beast-panel-head"><div><h3>Host & trust boundary</h3><span>Capability discovery is live; mutation remains operator-approved.</span></div>${pill(Boolean(g.delegation_proven),'DELEGATED','READ ONLY')}</header><div class="tiny">${caps.map(x=>`${x.name}: ${x.available?'available':'unavailable'}${x.mutable?' · mutable':''}`).join('<br>')||'Host capability state unavailable.'}</div>${issue('cgroup')}${issue('host')}`;
      root.querySelector('[data-control-continuity]').innerHTML=`<header class="beast-panel-head"><div><h3>Continuity & recovery</h3><span>Reboot recovery requires fresh attestation and recurrence verification.</span></div>${pill(b.postboot_receipt_present,'VERIFIED','PENDING')}</header><p>Preboot witness: ${b.preboot_witness_present?'present':'not prepared'}<br>Postboot receipt: ${b.postboot_receipt_present?'present':'not verified'}</p><p class="tiny">${esc(b.workflow||'Continuity workflow unavailable.')}</p>${issue('reboot')}`;
    };
    const unsubscribe=BeastStore.subscribe(render); render(BeastStore.get());
    root.addEventListener('click',async e=>{const a=e.target.closest('[data-control]')?.dataset.control;if(!a)return;try{if(a==='refresh')await BeastUtilityOrchestrationBridge.refreshControl();else await BeastUtilityOrchestrationBridge.reconcileServices();document.dispatchEvent(new CustomEvent('beast:operation',{detail:{message:`Compute control ${a} complete`,tone:'ok'}}));}catch(err){document.dispatchEvent(new CustomEvent('beast:operation',{detail:{message:String(err.message||err),tone:'error'}}));}});
    BeastUtilityOrchestrationBridge.refreshControl().catch(()=>{}); return {node:root,dispose(){disposed=true;unsubscribe?.();}};
  } window.BeastComputeControlPage={renderer};
})();
